import ast
from typing import List, Dict, Any
from dataclasses import dataclass

@dataclass
class FunctionMetadata:
    name: str
    args: List[str]
    returns: Any
    branches: int
    complexity: int

class CodeAnalyzer(ast.NodeVisitor):
    """
    Performs deep static analysis of Python source code to extract 
    structural metadata for test generation.
    """
    def __init__(self):
        self.functions: Dict[str, FunctionMetadata] = {}
        self._current_func = None
        self._branch_count = 0

    def visit_FunctionDef(self, node: ast.FunctionDef):
        self._current_func = node.name
        self._branch_count = 0
        
        # Analyze arguments
        args = [arg.arg for arg in node.args.args]
        
        # Analyze return type
        returns = ast.unparse(node.returns) if node.returns else "Any"
        
        # Walk the function body to count branches
        for child in ast.walk(node):
            if isinstance(child, (ast.If, ast.While, ast.For, ast.ExceptHandler)):
                self._branch_count += 1
        
        self.functions[node.name] = FunctionMetadata(
            name=node.name,
            args=args,
            returns=returns,
            branches=self._branch_count,
            complexity=self._branch_count + 1
        )
        self.generic_visit(node)

    def analyze_source(self, source_code: str) -> Dict[str, FunctionMetadata]:
        tree = ast.parse(source_code)
        self.visit(tree)
        return self.functions